import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Heading, IconButton, Stack} from '@primer/react'
import {useState} from 'react'
import {ResourceCard, type ResourceCardProps} from './ResourceCard/ResourceCard'
import styles from './ResourceCards.module.css'

export interface ResourceCardsProps {
  /**
   * Heading text to display above the resource cards
   */
  heading: string
  /**
   * Text for the dismiss/remove action in the options menu
   */
  dismissText: string
  /**
   * Whether the component is currently dismissed/hidden. This is a
   * controlled prop: the component will render null when `dismissed` is
   * true. Use `onDismiss` to be notified of user dismiss actions.
   */
  dismissed: boolean
  /**
   * Optional callback invoked when the user dismisses the component. Use
   * this to persist the dismissed state in the parent if desired.
   */
  onDismiss?: () => void
  /**
   * An array of resource card data to display.
   */
  resourceCards: ResourceCardProps[]
}

export function ResourceCards({heading, dismissText, dismissed, onDismiss, resourceCards}: ResourceCardsProps) {
  const [isDismissed, setIsDismissed] = useState<boolean>(dismissed)

  const handleDismiss = () => {
    onDismiss?.()
    setIsDismissed(true)
  }

  return isDismissed ? null : (
    <section aria-labelledby="resources-heading" data-testid="resources-section">
      <Stack direction="vertical" gap="normal" className={styles.container}>
        <Stack direction="horizontal" justify="space-between" align="center">
          <Heading as="h2" id="resources-heading" className={styles.heading}>
            {heading}
          </Heading>
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton
                icon={KebabHorizontalIcon}
                aria-label="Remove section"
                variant="invisible"
                data-testid="resources-options"
              />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay align="end">
              <ActionList>
                <ActionList.Item onSelect={handleDismiss} data-testid="resources-remove-option">
                  {dismissText}
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Stack>
        <ul className={styles.grid}>
          {resourceCards.map(card => (
            <li key={card.title}>
              <ResourceCard {...card} />
            </li>
          ))}
        </ul>
      </Stack>
    </section>
  )
}
