import {Button, Heading, IconButton} from '@primer/react'
import {XIcon} from '@primer/octicons-react'
import {useClickAnalytics} from '@github-ui/use-analytics'
import styles from './DownloadCard.module.css'
import {useState} from 'react'
import type {Dispatch, SetStateAction} from 'react'

interface Analytics {
  category: string
  action: string
}

export interface DownloadCardData {
  /**
   * Whether the card is currently dismissed/hidden. This is a
   * controlled prop: the component will render null when `dismissed` is
   * true. Use `onDismiss` to be notified of user dismiss actions.
   */
  dismissed: boolean
  /**
   * Optional callback invoked when the user dismisses the card. Use
   * this to persist the dismissed state in the parent if desired.
   */
  onDismiss?: () => void
  /**
   * The title text to display in the card header
   */
  title: string
  /**
   * The description text to display below the title. Can be empty.
   */
  description?: string
  /**
   * URL path to the icon image to display at the top of the card
   */
  icon: string
  /**
   * The download URL that the download button will link to
   */
  href: string
  /**
   * Whether to open the download link in a new tab/window.
   * When true, adds target="_blank" and rel="noopener noreferrer" to the link.
   * @default false
   */
  openInNewTab?: boolean
  /**
   * Optional analytics tracking configuration for the download button click
   */
  analytics?: Analytics
}

export interface DownloadCardProps extends DownloadCardData {
  /**
   * Callback to update the list of cards in the parent.
   */
  setCards: Dispatch<SetStateAction<DownloadCardData[]>>
}

export const DownloadCard = ({
  dismissed,
  onDismiss,
  setCards,
  title,
  description,
  icon,
  href,
  openInNewTab = false,
  analytics,
}: DownloadCardProps) => {
  const [isDismissed, setIsDismissed] = useState<boolean>(dismissed)

  const handleDismiss = () => {
    onDismiss?.()
    setIsDismissed(true)
    setCards(prev => prev.map(card => (card.title === title ? {...card, dismissed: true} : card)))
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  // Turns title into a lowercase string with underscores and removes non-word characters
  const sanitizedTitle = title
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^\w_]/g, '')

  return isDismissed ? null : (
    <div className={styles.card} data-testid={`download-card-${sanitizedTitle}`}>
      <img src={icon} alt={title} className={styles.icon} />
      <div>
        <Heading as="h3" className={styles.heading}>
          {title}
        </Heading>
        {description ? <div className={styles.description}>{description}</div> : null}
        <Button
          as="a"
          href={href}
          target={openInNewTab ? '_blank' : undefined}
          rel={openInNewTab ? 'noopener noreferrer' : undefined}
          aria-label={title}
          onClick={() => {
            if (!analytics) return

            sendClickAnalyticsEvent({
              category: analytics.category,
              action: analytics.action,
            })
          }}
          data-testid={`download-card-${sanitizedTitle}-download`}
        >
          Download
        </Button>
      </div>
      <IconButton
        aria-label="Dismiss"
        data-testid={`download-card-${sanitizedTitle}-dismiss`}
        size="small"
        variant="invisible"
        icon={XIcon}
        className={styles.dismissButton}
        onClick={handleDismiss}
      />
    </div>
  )
}
