import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Heading, IconButton, Stack} from '@primer/react'
import {useEffect, useState} from 'react'
import {DownloadCard, type DownloadCardData} from './DownloadCard/DownloadCard'
import styles from './DownloadCards.module.css'

export interface DownloadCardsProps {
  /**
   * Heading text to display above the download cards
   */
  heading: string
  /**
   * Text for the dismiss/remove action in the options menu
   */
  dismissText: string
  /**
   * Whether the component is currently dismissed/hidden. This is a
   * controlled prop: the component will render null when `dismissed` is
   * true. Use `onDismiss` to be notified of user dismiss actions.
   */
  dismissed: boolean
  /**
   * Optional callback invoked when the user dismisses the component. Use
   * this to persist the dismissed state in the parent if desired.
   */
  onDismiss?: () => void
  /**
   * An array of download card data to display.
   */
  downloadCards: DownloadCardData[]
}

export function DownloadCards({heading, dismissText, dismissed, onDismiss, downloadCards}: DownloadCardsProps) {
  const [manuallyDismissed, setManuallyDismissed] = useState<boolean>(false)
  const [cards, setCards] = useState<DownloadCardData[]>(downloadCards)

  const handleDismiss = () => {
    onDismiss?.()
    setManuallyDismissed(true)
  }

  // Derive the dismissed state - component is dismissed if the prop says so,
  // manually dismissed, or all cards are dismissed
  const allCardsDismissed = cards.every(card => card.dismissed)
  const isDismissed = dismissed || manuallyDismissed || allCardsDismissed

  // When all cards are dismissed, call onDismiss to notify parent
  useEffect(() => {
    if (allCardsDismissed && !dismissed && !manuallyDismissed) {
      onDismiss?.()
    }
  }, [allCardsDismissed, dismissed, manuallyDismissed, onDismiss])

  return isDismissed ? null : (
    <section aria-labelledby="downloads-heading" data-testid="downloads-section">
      <Stack direction="vertical" gap="normal" className={styles.container}>
        <Stack direction="horizontal" justify="space-between" align="center">
          <Heading as="h2" id="downloads-heading" className={styles.heading}>
            {heading}
          </Heading>
          <ActionMenu>
            <ActionMenu.Anchor>
              <IconButton
                icon={KebabHorizontalIcon}
                aria-label="Remove section"
                variant="invisible"
                data-testid="downloads-options"
              />
            </ActionMenu.Anchor>
            <ActionMenu.Overlay align="end">
              <ActionList>
                <ActionList.Item onSelect={handleDismiss} data-testid="downloads-remove-option">
                  {dismissText}
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Stack>
        <ul className={styles.grid}>
          {cards.map(card =>
            card.dismissed ? null : (
              <li key={card.title} className={styles.listItem}>
                <DownloadCard {...card} setCards={setCards} />
              </li>
            ),
          )}
        </ul>
      </Stack>
    </section>
  )
}
