import {Stack, registerPortalRoot} from '@primer/react'
import BeginnersPlaylist from './components/BeginnerPlaylist/BeginnersPlaylist'
import {NewUserGettingStartedChecklist} from './components/NewUserGettingStartedChecklist/NewUserGettingStartedChecklist'
import {NuxDashboardDocs} from './components/NuxDashboardDocs/NuxDashboardDocs'
import {Recommendations} from './components/Recommendations/Recommendations'
import type {Dismissals} from './types/dismissals-types'
import {allModulesDismissed} from './helpers/dismissals-helper'
import {useEffect, useId, useRef, useState} from 'react'
import type {GettingStartedChecklist, ChecklistActions} from './types/checklist-types'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {DownloadCards} from '@github-ui/download-cards'
import {ResourceCards} from '@github-ui/resource-cards'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {getRecommendationCards} from './helpers/recommendations-helper'
import {DashboardDismissalSettings} from './constants/dashboard-settings'
import {updateSetting} from './helpers/settings-helper'
import {getResourceCards} from './helpers/ResourcesHelper'

export interface NuxDashboardRefreshProps {
  new_user_getting_started_checklist: GettingStartedChecklist
  checklist_actions: ChecklistActions
  dismissals: Dismissals
}

export function NuxDashboardRefresh({
  new_user_getting_started_checklist,
  checklist_actions,
  dismissals,
}: NuxDashboardRefreshProps) {
  const [dismissedModules, setDismissedModules] = useState<Dismissals>({
    ...dismissals,
  })

  const portalContainerRef = useRef<HTMLDivElement | null>(null)
  const portalContainerName = `nux-dashboard-refresh-portal-${useId()}`

  useEffect(() => {
    if (portalContainerRef.current) {
      registerPortalRoot(portalContainerRef.current, portalContainerName)
    }
  }, [portalContainerName])

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  if (allModulesDismissed(dismissedModules)) return null

  const dashboardContent = isFeatureEnabled('zero_user_dashboard_alternate_layout') ? (
    <Stack direction="vertical" gap="normal" className="tmp-mb-3">
      <NewUserGettingStartedChecklist
        checklist={new_user_getting_started_checklist}
        checklistActions={checklist_actions}
        dismissed={dismissals.getting_started_dismissed}
        setDismissedModules={setDismissedModules}
        portalContainerName={portalContainerName}
      />
      <ResourceCards
        heading="Resources"
        dismissText="Remove from dashboard"
        dismissed={dismissals.docs_dismissed}
        onDismiss={() => {
          updateSetting(DashboardDismissalSettings.Docs, true)
          setDismissedModules(prev => ({...prev, docs_dismissed: true}))

          sendClickAnalyticsEvent({
            category: 'alt_zero_user_dashboard',
            action: 'click.resources.dismiss',
          })
        }}
        resourceCards={getResourceCards()}
      />
      <DownloadCards
        heading="Recommendations"
        dismissText="Remove from dashboard"
        dismissed={dismissals.recommendations_dismissed}
        downloadCards={getRecommendationCards(
          {
            vscodeDismissed: dismissals.vscode_dismissed,
            desktopDismissed: dismissals.desktop_dismissed,
          },
          sendClickAnalyticsEvent,
        )}
        onDismiss={() => {
          updateSetting(DashboardDismissalSettings.Recommendations, true)
          setDismissedModules(prev => ({...prev, recommendations_dismissed: true}))

          sendClickAnalyticsEvent({
            category: 'alt_zero_user_dashboard',
            action: 'click.recommendations.dismiss',
          })
        }}
      />
    </Stack>
  ) : (
    <Stack direction="vertical" gap="normal" className="tmp-mb-3">
      <BeginnersPlaylist dismissed={dismissals.playlist_dismissed} setDismissedModules={setDismissedModules} />
      <NewUserGettingStartedChecklist
        checklist={new_user_getting_started_checklist}
        checklistActions={checklist_actions}
        dismissed={dismissals.getting_started_dismissed}
        setDismissedModules={setDismissedModules}
        portalContainerName={portalContainerName}
      />
      <NuxDashboardDocs
        heading="Start with GitHub Docs"
        dismissed={dismissals.docs_dismissed}
        setDismissedModules={setDismissedModules}
        portalContainerName={portalContainerName}
      />
      <Recommendations
        dismissed={dismissals.recommendations_dismissed}
        recommendationDismissals={{
          vscodeDismissed: dismissals.vscode_dismissed,
          desktopDismissed: dismissals.desktop_dismissed,
        }}
        setDismissedModules={setDismissedModules}
        portalContainerName={portalContainerName}
      />
    </Stack>
  )

  return (
    <>
      <div ref={portalContainerRef} data-testid="nux-dashboard-portal-root" />
      {dashboardContent}
    </>
  )
}
